import java.util.List;
import java.util.Map;

public class TestValidate {

    static Map<String, Integer> codes = new HashMap<>();
    static String lastBody;
    static Map<String, String> lastHeaders = new HashMap<>();
    static String lastMethod;
    static String lastUrl;

    static class FakeConn extends HttpURLConnection {
        private final ByteArrayOutputStream buf = new ByteArrayOutputStream();
        FakeConn(URL u) { super(u); }
        @Override public void connect() {}
        @Override public void disconnect() {}
        @Override public boolean usingProxy() { return false; }
        @Override public void setRequestMethod(String m) { lastMethod = m; }
        @Override public void setRequestProperty(String k, String v) { lastHeaders.put(k, v); }
        @Override public void setConnectTimeout(int t) {}
        @Override public void setReadTimeout(int t) {}
        @Override public void setDoOutput(boolean b) {}
        @Override public OutputStream getOutputStream() {
            return new FilterOutputStream(buf) {
                @Override public void close() throws IOException {
                    super.close();
                    lastBody = buf.toString("UTF-8");
                }
            };
        }
        @Override public int getResponseCode() {
            String key = lastMethod + " " + getURL().getPath();
            Integer c = codes.get(key);
            if (c == null) c = codes.get(lastMethod + " *");
            return c != null ? c : 200;
        }
    }

    public static void main(String[] args) throws Exception {
        URL.setURLStreamHandlerFactory(protocol -> {
            if ("http".equals(protocol)) {
                return new URLStreamHandler() {
                    @Override protected URLConnection openConnection(URL u) {
                        lastUrl = u.toString();
                        return new FakeConn(u);
                    }
                };
            }
            return null;
        });

        User user = User.builder().id(1L).username("admin").password("x").role("ADMIN").createdAt(LocalDateTime.now()).build();
        UserMapper userMapper = (UserMapper) Proxy.newProxyInstance(TestValidate.class.getClassLoader(),
                new Class<?>[]{UserMapper.class}, (proxy, m, a) -> {
                    if (m.getName().equals("findByUsername")) return user;
                    if (m.getName().equals("findById")) return user;
                    if (m.getName().equals("count")) return 1;
                    return null;
                });

        final ModelProvider[] stored = new ModelProvider[1];
        final boolean[] updated = {false};
        ModelProviderMapper mpMapper = (ModelProviderMapper) Proxy.newProxyInstance(TestValidate.class.getClassLoader(),
                new Class<?>[]{ModelProviderMapper.class}, (proxy, m, a) -> {
                    switch (m.getName()) {
                        case "findById": return stored[0];
                        case "findByUserId": return List.of(stored[0]);
                        case "insert": stored[0] = (ModelProvider) a[0]; return null;
                        case "update": updated[0] = true; return null;
                    }
                    return null;
                });

        ProviderService svc = new ProviderService();
        Field f1 = ProviderService.class.getDeclaredField("userMapper"); f1.setAccessible(true); f1.set(svc, userMapper);
        Field f2 = ProviderService.class.getDeclaredField("modelProviderMapper"); f2.setAccessible(true); f2.set(svc, mpMapper);

        // scenario A: phase-1 401 -> INVALID
        run(svc, stored, updated, "bad", Map.of("GET /models/bad", 401), "A phase1-401");
        // scenario B: phase-1 404 -> phase-2 401 -> INVALID
        run(svc, stored, updated, "post401", Map.of("GET /models/post401", 404, "POST /v1/chat/completions", 401), "B phase2-401");
        // scenario C: phase-1 404 -> phase-2 200 -> VALID
        run(svc, stored, updated, "ok", Map.of("GET /models/ok", 404, "POST /v1/chat/completions", 200), "C phase2-200");
        // scenario D: phase-1 200 -> VALID
        run(svc, stored, updated, "fine", Map.of("GET /models/fine", 200), "D phase1-200");
        // scenario E: phase-1 -1 (exception) -> phase-2 -1 -> ERROR Connection failed
        codes.put("GET /models/dead", null); // force via exception below
        run(svc, stored, updated, "dead", Map.of("POST /v1/chat/completions", 200), "E phase1-exception");
        // scenario F: blocked url -> not contacted
        stored[0] = provider(1L, "http://127.0.0.1:9090", "k", "m");
        updated[0] = false;
        ModelProvider r = svc.validateProvider(1L, "admin");
        System.out.println("F blocked-url: status=" + r.getStatus() + " err=" + r.getErrorMessage() + " updated=" + updated[0] + " ts=" + (r.getLastValidatedAt() != null));
        // scenario G: wrong owner -> null, no update
        stored[0] = provider(99L, "http://example.com", "k", "m");
        updated[0] = false;
        ModelProvider r2 = svc.validateProvider(1L, "admin");
        System.out.println("G wrong-owner: result=" + r2 + " updated=" + updated[0]);
        // scenario H: missing provider -> null
        stored[0] = null;
        System.out.println("H missing: result=" + svc.validateProvider(5L, "admin"));
    }

    static ModelProvider provider(Long userId, String baseUrl, String apiKey, String modelId) {
        return ModelProvider.builder().id(1L).userId(userId).name("n").baseUrl(baseUrl).apiKey(apiKey)
                .modelId(modelId).status("PENDING").createdAt(LocalDateTime.now()).build();
    }

    static void run(ProviderService svc, ModelProvider[] stored, boolean[] updated, String modelId, Map<String, Integer> scenarioCodes, String label) throws Exception {
        codes.clear();
        codes.putAll(scenarioCodes);
        stored[0] = provider(1L, "http://fake.test", "sk-abc", modelId);
        updated[0] = false;
        lastBody = null;
        ModelProvider r = svc.validateProvider(1L, "admin");
        System.out.println(label + ": status=" + r.getStatus() + " err=" + r.getErrorMessage()
                + " updated=" + updated[0] + " ts=" + (r.getLastValidatedAt() != null)
                + (lastBody != null ? " postBody=" + lastBody : "")
                + (lastHeaders.get("Authorization") != null ? " auth=" + lastHeaders.get("Authorization") : ""));
    }
}
